import { Ratelimit } from '@upstash/ratelimit'
import { Redis } from '@upstash/redis'

/**
 * Upstash Redis rate limiters — three tiers.
 * In dev without UPSTASH_REDIS_REST_URL/TOKEN, returns a no-op stub that always allows.
 */

type Limiter = {
  limit: (identifier: string) => Promise<{
    success: boolean
    limit: number
    remaining: number
    reset: number
  }>
}

const hasUpstash = Boolean(
  process.env.UPSTASH_REDIS_REST_URL && process.env.UPSTASH_REDIS_REST_TOKEN
)

const noop: Limiter = {
  async limit() {
    return { success: true, limit: 9999, remaining: 9999, reset: Date.now() + 60_000 }
  },
}

function make(prefix: string, requests: number, window: `${number} ${'s' | 'm'}`): Limiter {
  if (!hasUpstash) return noop
  return new Ratelimit({
    redis: Redis.fromEnv(),
    limiter: Ratelimit.slidingWindow(requests, window),
    analytics: true,
    prefix,
  })
}

export const apiRatelimit = make('rl:api', 10, '10 s')
export const authedRatelimit = make('rl:auth', 60, '1 m')
