import pino from 'pino'

/**
 * Structured pino logger.
 *
 * In production (Railway), outputs JSON that Railway aggregates and makes
 * searchable. In development, pino-pretty formats the output for readability.
 *
 * NEVER use console.log in production code — ESLint will block it.
 */
export const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  formatters: {
    level: (label) => ({ level: label }),
  },
  base: {
    env: process.env.NEXT_PUBLIC_APP_ENV ?? 'development',
    service: 'inkos-web',
    version: process.env.RAILWAY_DEPLOYMENT_ID ?? 'local',
  },
  redact: {
    paths: [
      'req.headers.authorization',
      'req.headers.cookie',
      '*.password',
      '*.token',
      '*.api_key',
      '*.apiKey',
      '*.secret',
      '*.webhook_key',

export function createServiceRoleClient() {
  const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY
  if (!serviceRoleKey) {
    throw new Error('SUPABASE_SERVICE_ROLE_KEY is not set')
  }

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    serviceRoleKey,
    {
      cookies: {
        getAll() {
          return []
        },
        setAll() {
          // No-op for service role — no session cookies
        },
      },
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    }
  )
}
