import { Worker } from 'bullmq'
import IORedis from 'ioredis'
import pino from 'pino'
import { handleSendEmail } from './handlers/send-email'

const logger = pino({
  level: process.env['LOG_LEVEL'] ?? 'info',
  ...(process.env['NODE_ENV'] === 'development' && {
    transport: { target: 'pino-pretty', options: { colorize: true } },
  }),
})

/**
 * IORedis connection for BullMQ.
 *
 * REQUIRED: maxRetriesPerRequest must be null for BullMQ.
 * Uses REDIS_PRIVATE_URL (Railway internal DNS) in production.
 */
const redisUrl = process.env['REDIS_PRIVATE_URL']
if (!redisUrl) {
  logger.fatal('REDIS_PRIVATE_URL is required — worker cannot start without Redis')
  process.exit(1)
}

const connection = new IORedis(redisUrl, {
  maxRetriesPerRequest: null,
  enableReadyCheck: false,
  lazyConnect: true,
})

connection.on('connect', () => logger.info('redis connected'))
connection.on('error', (err) => logger.error({ err }, 'redis error'))

/**
 * BullMQ worker — processes jobs from the inkos-jobs queue.
 *
 * Add job handlers below as sprints ship new features.
 * Each handler is a separate file in src/handlers/.
 */
const worker = new Worker(
  'inkos-jobs',
  async (job) => {
    const log = logger.child({ jobId: job.id, name: job.name, attempt: job.attemptsMade + 1 })
    log.info('processing job')

    switch (job.name) {
      case 'send-email':
        await handleSendEmail(job.data as Parameters<typeof handleSendEmail>[0])
        break
      case 'generate-consent-pdf':
        log.info('generate-consent-pdf — Sprint 5')
        break
