/**
 * Consent form section type definitions.
 * These types describe the JSONB structure stored in consent_form_templates.sections.
 * Immutable once any submission references the template version.
 */

export type ConsentSectionKind =
  | 'heading'
  | 'paragraph'
  | 'signature'
  | 'initials'
  | 'checkbox'
  | 'text_input'
  | 'date'
  | 'dropdown'
  | 'file_upload'
  | 'ink_disclosure'
  | 'reach_batch_record'

export interface BaseSectionFields {
  id: string           // nanoid(10) — stable across edits
  kind: ConsentSectionKind
  label: string        // shown above section to signer
  required: boolean
  order: number        // integer, 0-indexed, contiguous
}

export interface HeadingSection extends BaseSectionFields {
  kind: 'heading'
  level: 1 | 2 | 3    // maps to text-2xl / text-xl / text-lg
}

export interface ParagraphSection extends BaseSectionFields {
  kind: 'paragraph'
  body: string         // markdown, rendered via react-markdown
}

export interface SignatureSection extends BaseSectionFields {
  kind: 'signature'
  signer: 'client' | 'guardian'
}

export interface InitialsSection extends BaseSectionFields {
  kind: 'initials'
  body: string         // markdown — text to initial
}

export interface CheckboxSection extends BaseSectionFields {
  kind: 'checkbox'
  body: string         // markdown text of the checkbox statement
}

export interface TextInputSection extends BaseSectionFields {
  kind: 'text_input'
  placeholder?: string
  min_length?: number
  max_length?: number
  regex?: string | null
  regex_error?: string | null
}

export interface DateSection extends BaseSectionFields {
  kind: 'date'
  min_age?: number     // e.g. 18 — shows warning if DOB is under this age
}

export interface DropdownSection extends BaseSectionFields {
  kind: 'dropdown'
  options: Array<{ value: string; label: string }>
}

export interface FileUploadSection extends BaseSectionFields {
  kind: 'file_upload'
  accept: string[]     // e.g. ['image/jpeg','image/png','application/pdf']
  max_size_mb: number  // default 5
}

export interface InkDisclosureSection extends BaseSectionFields {
  kind: 'ink_disclosure'
  disclosure_text: string  // markdown, REACH-compliant, editable in template
}

export interface ReachBatchRecordSection extends BaseSectionFields {
  kind: 'reach_batch_record'
  artist_instructions: string  // shown in authed submission view for artist
}

export type ConsentSection =
  | HeadingSection
  | ParagraphSection
  | SignatureSection
  | InitialsSection
  | CheckboxSection
  | TextInputSection
  | DateSection
  | DropdownSection
  | FileUploadSection
  | InkDisclosureSection
  | ReachBatchRecordSection

// ── Submission answer shapes ────────────────────────────────────────────────

export interface ReachBatchAnswer {
  ink_brand: string
  ink_color: string
  ink_product_code?: string | null
  batch_number: string
  manufacture_date?: string | null
  expiry_date?: string | null
  reach_compliant: boolean
  sds_url?: string | null
}

export type SectionAnswerValue =
  | boolean
  | string
  | ReachBatchAnswer
  | null

export type SectionAnswers = Record<string, SectionAnswerValue>

// ── Public consent request payload (from get_consent_request RPC) ──────────

export interface PublicConsentRequest {
  request_id: string
  request_token: string
  template: {
    id: string
    name: string
    kind: string
    version: number
    sections: ConsentSection[]
    requires_guardian: boolean
    retention_years: number
    language: string
  }
  studio: {
    name: string
    logo_url: string | null
    brand_color: string | null
    slug: string
  }
  client: {
    first_name: string
    last_name: string | null
    email: string | null
  } | null
  booking: {
    scheduled_at: string
    service_name: string | null
    artist_name: string | null
  } | null
  status: 'pending' | 'opened' | 'signed' | 'cancelled' | 'expired'
  expires_at: string | null
  error?: string
}

// ── Public submit payload ────────────────────────────────────────────────────

export interface PublicSubmitPayload {
  request_token: string
  answers: SectionAnswers
  signature_png_base64: string
  signer_name: string
  signer_email?: string | null
  signer_phone?: string | null
  signer_dob?: string | null
  guardian?: {
    name: string
    relationship: string
    signature_png_base64: string
  } | null
  ink_records?: ReachBatchAnswer[] | null
}

export interface PublicSubmitResult {
  consent_token: string
  submission_id: string
  signature_path: string
  guardian_path?: string | null
  view_url: string
  status: 'signed'
  error?: never
}

export interface PublicSubmitError {
  error: 'already_signed' | 'expired' | 'request_cancelled' | 'request_not_found' | 'submission_failed'
  status?: never
}

export type PublicSubmitResponse = PublicSubmitResult | PublicSubmitError

// ── Template kind badge ──────────────────────────────────────────────────────

export type TemplateKind = 'tattoo' | 'piercing' | 'pmu' | 'touch_up' | 'minor' | 'custom'

// ── Submission status ────────────────────────────────────────────────────────

export type SubmissionStatus = 'signed' | 'expired' | 'soft_deleted' | 'pending' | 'opened'

// ── localStorage draft ───────────────────────────────────────────────────────

export interface ConsentDraftProgress {
  answers: SectionAnswers
  completedSections: string[]
  savedAt: string
}

