/**
 * Signature PNG validation helpers.
 * Called on the server before passing base64 to Supabase Storage.
 */

const MAX_SIGNATURE_BYTES = 500 * 1024  // 500 KB
const VALID_PNG_PREFIX = 'data:image/png;base64,'

export interface SignatureValidationResult {
  valid: boolean
  error?: string
  buffer?: Buffer
}

/**
 * Validate that a base64 string is a genuine PNG under 500 KB.
 * Returns the decoded Buffer for immediate upload.
 */
export function validateSignatureBase64(
  base64: string,
  fieldName = 'signature'
): SignatureValidationResult {
  if (!base64) {
    return { valid: false, error: `${fieldName} is required` }
  }

  // Accept with or without the data: prefix
  let raw = base64
  if (raw.startsWith('data:')) {
    if (!raw.startsWith(VALID_PNG_PREFIX)) {
      return { valid: false, error: `${fieldName} must be a PNG image` }
    }
    raw = raw.slice(VALID_PNG_PREFIX.length)
  }

  // Verify it's valid base64
  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(raw)) {
    return { valid: false, error: `${fieldName} contains invalid base64 characters` }
  }

  let buffer: Buffer
  try {
    buffer = Buffer.from(raw, 'base64')
  } catch {
    return { valid: false, error: `${fieldName} could not be decoded` }
  }

  // Verify PNG magic bytes: 89 50 4E 47 0D 0A 1A 0A
  if (
    buffer.length < 8 ||
    buffer[0] !== 0x89 ||
    buffer[1] !== 0x50 ||
    buffer[2] !== 0x4e ||
    buffer[3] !== 0x47
  ) {
    return { valid: false, error: `${fieldName} is not a valid PNG file` }
  }

  if (buffer.length > MAX_SIGNATURE_BYTES) {
    return {
      valid: false,
      error: `${fieldName} exceeds the 500 KB maximum size (${(buffer.length / 1024).toFixed(0)} KB)`,
    }
  }

  return { valid: true, buffer }
}

/**
 * Upload a validated signature buffer to Supabase Storage.
 * Uses the service-role client to bypass RLS.
 * Path convention: {studio_id}/{submission_id}/{filename}.png
 */
export async function uploadSignaturePng(
  serviceRoleClient: ReturnType<typeof import('@/lib/supabase/server').createServiceRoleClient>,
  buffer: Buffer,
  storagePath: string
): Promise<void> {
  const { error } = await serviceRoleClient.storage
    .from('consent-forms')
    .upload(storagePath, buffer, {
      contentType: 'image/png',
      upsert: true,
    })

  if (error) {
    throw new Error(`Signature upload failed at ${storagePath}: ${error.message}`)
  }
}

import { NextRequest } from 'next/server'
import { createPublicClient } from '@/lib/supabase/public'
import { publicConsentReadRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

/**
 * GET /api/public/consent/requests/[token]
 *
 * Anon-accessible. Fetches consent request data via get_consent_request RPC.
 * Side effect: flips status pending → opened on first call.
 * Rate limit: 20/min per IP.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ token: string }> }
) {
  const ip = request.headers.get('x-forwarded-for') ?? 'anonymous'
  const { success } = await publicConsentReadRatelimit.limit(ip)
  if (!success) {
    return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })
  }

  const { token } = await params
  if (!token || !/^[0-9a-f-]{36}$/.test(token)) {
    return Response.json({ error: 'request_not_found' }, { status: 404 })
  }

  const supabase = createPublicClient()
  const { data, error } = await supabase.rpc('get_consent_request', {
    p_token: token,
  })

  if (error) {
    logger.error({ err: error, token }, 'get_consent_request RPC failed')
    return Response.json({ error: 'request_not_found' }, { status: 404 })
  }

  if (!data) {
    return Response.json({ error: 'request_not_found' }, { status: 404 })
  }

  // RPC returns error string on known failures
  const result = data as Record<string, unknown>
  if (result['error']) {
    const status =
      result['error'] === 'already_signed' ? 200
      : result['error'] === 'request_expired' ? 410
      : 404
    return Response.json(data, { status })
  }

  return Response.json(data)
}

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createPublicClient } from '@/lib/supabase/public'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { publicConsentSubmitRatelimit } from '@/lib/rate-limit'
import { validateSignatureBase64, uploadSignaturePng } from '@/lib/consent/validate-signature'
import { enqueueJob } from '@/lib/queue'
import { logger } from '@/lib/logger'

/**
 * POST /api/public/consent/submit
 *
 * Anon-accessible. Validates and submits a signed consent form.
 * Rate limit: 3/min per IP.
 *
 * Flow:
 * 1. Rate limit check
 * 2. Zod parse + signature validation
 * 3. Call submit_consent_form RPC → get deterministic storage paths
 * 4. Upload PNG(s) to Supabase Storage using service-role client
 * 5. Enqueue PDF generation job
 * 6. Return consent_token + view_url
 */

const ReachBatchSchema = z.object({
  ink_brand: z.string().min(1).max(200),
  ink_color: z.string().min(1).max(200),
  ink_product_code: z.string().max(200).nullable().optional(),
  batch_number: z.string().min(1).max(200),
  manufacture_date: z.string().nullable().optional(),
  expiry_date: z.string().nullable().optional(),
  reach_compliant: z.boolean(),
  sds_url: z.string().url().nullable().optional(),
})

const GuardianSchema = z.object({
  name: z.string().min(1).max(200),
  relationship: z.string().min(1).max(100),
  signature_png_base64: z.string().min(1),
})

const SubmitBodySchema = z.object({
  request_token: z.string().uuid(),
  answers: z.record(z.string(), z.unknown()),
  signature_png_base64: z.string().min(1),
  signer_name: z.string().min(1).max(200),
  signer_email: z.string().email().nullable().optional(),
  signer_phone: z.string().max(30).nullable().optional(),
  signer_dob: z.string().nullable().optional(),
  guardian: GuardianSchema.nullable().optional(),
  ink_records: z.array(ReachBatchSchema).nullable().optional(),
})

export async function POST(request: NextRequest) {
  const ip = request.headers.get('x-forwarded-for') ?? 'anonymous'
  const { success } = await publicConsentSubmitRatelimit.limit(ip)
  if (!success) {
    return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })
  }

  let rawBody: unknown
  try {
    rawBody = await request.json()
  } catch {
    return Response.json({ error: 'invalid_json' }, { status: 400 })
  }

  const parsed = SubmitBodySchema.safeParse(rawBody)
  if (!parsed.success) {
    return Response.json({ error: 'validation_error', details: parsed.error.flatten() }, { status: 400 })
  }

  const body = parsed.data

  // Validate main signature PNG
  const sigValidation = validateSignatureBase64(body.signature_png_base64, 'signature')
  if (!sigValidation.valid || !sigValidation.buffer) {
    return Response.json({ error: sigValidation.error }, { status: 400 })
  }

  // Validate guardian signature if present
  let guardianBuffer: Buffer | undefined
  if (body.guardian?.signature_png_base64) {
    const gValidation = validateSignatureBase64(body.guardian.signature_png_base64, 'guardian_signature')
    if (!gValidation.valid || !gValidation.buffer) {
      return Response.json({ error: gValidation.error }, { status: 400 })
    }
    guardianBuffer = gValidation.buffer
  }

  const supabase = createPublicClient()
  const serviceRole = createServiceRoleClient()

  // Call submit_consent_form RPC
  const { data: rpcResult, error: rpcError } = await supabase.rpc('submit_consent_form', {
    p_request_token: body.request_token,
    p_answers: body.answers as Record<string, unknown>,
    p_signature_png_base64: body.signature_png_base64,
    p_signer_name: body.signer_name,
    p_signer_email: body.signer_email ?? null,
    p_signer_phone: body.signer_phone ?? null,
    p_signer_dob: body.signer_dob ?? null,
    p_guardian: body.guardian
      ? {
          name: body.guardian.name,
          relationship: body.guardian.relationship,
          signature_png_base64: body.guardian.signature_png_base64,
        }
      : null,
    p_ink_records: body.ink_records ?? null,
  })

  if (rpcError) {
    logger.error({ err: rpcError, token: body.request_token }, 'submit_consent_form RPC error')
    return Response.json({ error: 'submission_failed' }, { status: 500 })
  }

  const result = rpcResult as Record<string, unknown>
  if (result['error']) {
    const httpStatus =
      result['error'] === 'already_signed' ? 409
      : result['error'] === 'expired' ? 410
      : result['error'] === 'request_cancelled' ? 410
      : result['error'] === 'request_not_found' ? 404
      : 500
    return Response.json(rpcResult, { status: httpStatus })
  }

  const signaturePath = result['signature_path'] as string
  const guardianPath = result['guardian_path'] as string | null | undefined
  const submissionId = result['submission_id'] as string
  const studioId = signaturePath.split('/')[0]  // path: {studio_id}/{submission_id}/signature.png

  // Upload signature PNG to storage
  try {
    await uploadSignaturePng(serviceRole, sigValidation.buffer, signaturePath)
  } catch (err) {
    logger.error({ err, signaturePath, submissionId }, 'signature upload failed')
    return Response.json({ error: 'submission_failed' }, { status: 500 })
  }

  // Upload guardian PNG if present
  if (guardianBuffer && guardianPath) {
    try {
      await uploadSignaturePng(serviceRole, guardianBuffer, guardianPath)
    } catch (err) {
      logger.error({ err, guardianPath, submissionId }, 'guardian signature upload failed')
      // Non-fatal — submission is recorded, PDF may be incomplete
    }
  }

  // Enqueue PDF generation
  try {
    await enqueueJob('generate-consent-pdf', { submissionId, studioId })
  } catch (err) {
    logger.error({ err, submissionId }, 'failed to enqueue consent PDF job — non-fatal')
  }

  return Response.json(rpcResult)
}

import { NextRequest } from 'next/server'
import { createPublicClient } from '@/lib/supabase/public'
import { publicConsentReadRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

/**
 * GET /api/public/consent/view/[consentToken]
 *
 * Anon-accessible. Returns public shareable view of a signed submission.
 * Does NOT return: audit_hash, ip_address, user_agent, guardian_signature_path.
 * Rate limit: 20/min per IP.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ consentToken: string }> }
) {
  const ip = request.headers.get('x-forwarded-for') ?? 'anonymous'
  const { success } = await publicConsentReadRatelimit.limit(ip)
  if (!success) {
    return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })
  }

  const { consentToken } = await params
  if (!consentToken || !/^[0-9a-f-]{36}$/.test(consentToken)) {
    return Response.json({ error: 'not_found' }, { status: 404 })
  }

  const supabase = createPublicClient()
  const { data, error } = await supabase.rpc('view_consent_submission', {
    p_consent_token: consentToken,
  })

  if (error) {
    logger.error({ err: error, consentToken }, 'view_consent_submission RPC failed')
    return Response.json({ error: 'not_found' }, { status: 404 })
  }

  if (!data) {
    return Response.json({ error: 'not_found' }, { status: 404 })
  }

  return Response.json(data)
}

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

const CreateTemplateSchema = z.object({
  name: z.string().min(1).max(200),
  slug: z.string().min(1).max(200).regex(/^[a-z0-9-]+$/, 'Slug must be lowercase letters, numbers, and hyphens'),
  kind: z.enum(['tattoo', 'piercing', 'pmu', 'touch_up', 'minor', 'custom']),
  sections: z.array(z.record(z.string(), z.unknown())).default([]),
  applicable_services: z.array(z.string().uuid()).nullable().optional(),
  required_for_booking: z.boolean().default(false),
  requires_guardian: z.boolean().default(false),
  retention_years: z.number().int().min(1).max(20).default(7),
  language: z.string().min(2).max(10).default('en'),
  is_default: z.boolean().default(false),
})

/**
 * GET /api/consent-forms/templates
 * List all active templates for the studio.
 */
export async function GET(request: NextRequest) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  const ip = request.headers.get('x-forwarded-for') ?? auth.user.id
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const kind = searchParams.get('kind')
  const activeOnly = searchParams.get('active') !== 'false'

  const supabase = await createClient()
  let query = supabase
    .from('consent_form_templates')
    .select('*')
    .eq('studio_id', auth.studioId)
    .order('kind')
    .order('version', { ascending: false })

  if (activeOnly) query = query.eq('is_active', true)
  if (kind) query = query.eq('kind', kind)

  const { data, error } = await query
  if (error) {
    logger.error({ err: error }, 'consent templates list failed')
    return Response.json({ error: 'database_error' }, { status: 500 })
  }

  return Response.json({ data })
}

/**
 * POST /api/consent-forms/templates
 * Create a new template.
 */
export async function POST(request: NextRequest) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  const ip = request.headers.get('x-forwarded-for') ?? auth.user.id
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })

  const body = CreateTemplateSchema.safeParse(await request.json().catch(() => null))
  if (!body.success) {
    return Response.json({ error: 'validation_error', details: body.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()
  const { data, error } = await supabase
    .from('consent_form_templates')
    .insert({
      studio_id: auth.studioId,
      created_by: auth.user.id,
      ...body.data,
      version: 1,
      is_active: true,
    })
    .select()
    .single()

  if (error) {
    if (error.code === '23505') {
      return Response.json({ error: 'slug_conflict', message: 'A template with this slug and version already exists' }, { status: 409 })
    }
    logger.error({ err: error }, 'consent template create failed')
    return Response.json({ error: 'database_error' }, { status: 500 })
  }

  await logAuditAction(auth.user.id, 'consent_template.created', { type: 'consent_form_template', id: data.id }, { name: data.name, kind: data.kind }, auth.studioId)
  return Response.json({ data }, { status: 201 })
}

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

const UpdateTemplateSchema = z.object({
  name: z.string().min(1).max(200).optional(),
  kind: z.enum(['tattoo', 'piercing', 'pmu', 'touch_up', 'minor', 'custom']).optional(),
  sections: z.array(z.record(z.string(), z.unknown())).optional(),
  applicable_services: z.array(z.string().uuid()).nullable().optional(),
  required_for_booking: z.boolean().optional(),
  requires_guardian: z.boolean().optional(),
  retention_years: z.number().int().min(1).max(20).optional(),
  language: z.string().min(2).max(10).optional(),
  is_default: z.boolean().optional(),
  is_active: z.boolean().optional(),
})

async function resolveTemplate(supabase: Awaited<ReturnType<typeof createClient>>, id: string, studioId: string) {
  return supabase
    .from('consent_form_templates')
    .select('*')
    .eq('id', id)
    .eq('studio_id', studioId)
    .single()
}

/**
 * GET /api/consent-forms/templates/[id]
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  const { id } = await params
  const supabase = await createClient()
  const { data, error } = await resolveTemplate(supabase, id, auth.studioId)

  if (error || !data) {
    return Response.json({ error: 'not_found' }, { status: 404 })
  }

  return Response.json({ data })
}

/**
 * PATCH /api/consent-forms/templates/[id]
 *
 * Metadata-only changes (name, applicable_services, is_default, etc.) update in place.
 * Section changes are blocked by the immutability trigger if submissions exist
 * (returns Postgres exception P0001 → surface "creates new version" prompt to client).
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  const ip = request.headers.get('x-forwarded-for') ?? auth.user.id
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })

  const { id } = await params
  const body = UpdateTemplateSchema.safeParse(await request.json().catch(() => null))
  if (!body.success) {
    return Response.json({ error: 'validation_error', details: body.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()

  // Verify ownership first
  const { data: existing, error: fetchError } = await resolveTemplate(supabase, id, auth.studioId)
  if (fetchError || !existing) {
    return Response.json({ error: 'not_found' }, { status: 404 })
  }

  const { data, error } = await supabase
    .from('consent_form_templates')
    .update(body.data)
    .eq('id', id)
    .eq('studio_id', auth.studioId)
    .select()
    .single()

  if (error) {
    // Immutability trigger raises P0001 when sections are changed on a used template
    if (error.code === 'P0001') {
      return Response.json(
        { error: 'immutability_violation', new_version: existing.version + 1, message: error.message },
        { status: 409 }
      )
    }
    logger.error({ err: error, id }, 'consent template update failed')
    return Response.json({ error: 'database_error' }, { status: 500 })
  }

  await logAuditAction(auth.user.id, 'consent_template.updated', { type: 'consent_form_template', id }, body.data as Record<string, unknown>, auth.studioId)
  return Response.json({ data })
}

/**
 * DELETE /api/consent-forms/templates/[id]
 * Archives the template (sets is_active = false). Never hard-deletes.
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return Response.json({ error: 'forbidden' }, { status: 403 })
