import { NextRequest } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

/**
 * GET /api/consent-forms/submissions
 * List submissions for the studio with optional filters.
 * Query params: template_id, client_id, booking_id, status, page, limit
 */
export async function GET(request: NextRequest) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  const ip = request.headers.get('x-forwarded-for') ?? auth.user.id
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const templateId = searchParams.get('template_id')
  const clientId = searchParams.get('client_id')
  const bookingId = searchParams.get('booking_id')
  const status = searchParams.get('status')
  const page = Math.max(0, parseInt(searchParams.get('page') ?? '0', 10))
  const limit = Math.min(100, Math.max(1, parseInt(searchParams.get('limit') ?? '50', 10)))
  const dateFrom = searchParams.get('date_from')
  const dateTo = searchParams.get('date_to')

  const supabase = await createClient()
  let query = supabase
    .from('consent_form_submissions')
    .select(`
      id,
      signer_name,
      signer_email,
      signed_at,
      expires_at,
      soft_deleted_at,
      pdf_path,
      pdf_generated_at,
      consent_token,
      template_id,
      template_version,
      booking_id,
      client_id,
      studio_id,
      created_at
    `, { count: 'exact' })
    .eq('studio_id', auth.studioId)
    .order('signed_at', { ascending: false })
    .range(page * limit, (page + 1) * limit - 1)

  if (templateId) query = query.eq('template_id', templateId)
  if (clientId) query = query.eq('client_id', clientId)
  if (bookingId) query = query.eq('booking_id', bookingId)
  if (dateFrom) query = query.gte('signed_at', dateFrom)
  if (dateTo) query = query.lte('signed_at', dateTo)

  if (status === 'signed') {
    query = query.is('soft_deleted_at', null)
  } else if (status === 'expired') {
    query = query.is('soft_deleted_at', null).lt('expires_at', new Date().toISOString())
  } else if (status === 'soft_deleted') {
    query = query.not('soft_deleted_at', 'is', null)
  }

  const { data, error, count } = await query
  if (error) {
    logger.error({ err: error }, 'consent submissions list failed')
    return Response.json({ error: 'database_error' }, { status: 500 })
  }

  return Response.json({ data, count, page, limit })
}

import { NextRequest } from 'next/server'
