/**
 * GET /api/consent-forms/submissions/[id]
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  const { id } = await params
  const supabase = await createClient()
  const { data, error } = await supabase
    .from('consent_form_submissions')
    .select('*')
    .eq('id', id)
    .eq('studio_id', auth.studioId)
    .single()

  if (error || !data) {
    return Response.json({ error: 'not_found' }, { status: 404 })
  }

  // Generate a signed URL for the signature image (1 hour TTL)
  let signatureUrl: string | null = null
  let guardianSignatureUrl: string | null = null
  let pdfUrl: string | null = null

  if (data.signature_path) {
    const { data: signedData } = await supabase.storage
      .from('consent-forms')
      .createSignedUrl(data.signature_path, 3600)
    signatureUrl = signedData?.signedUrl ?? null
  }

  if (data.guardian_signature_path) {
    const { data: signedGuardian } = await supabase.storage
      .from('consent-forms')
      .createSignedUrl(data.guardian_signature_path, 3600)
    guardianSignatureUrl = signedGuardian?.signedUrl ?? null
  }

  if (data.pdf_path) {
    const { data: signedPdf } = await supabase.storage
      .from('consent-forms')
      .createSignedUrl(data.pdf_path, 3600)
    pdfUrl = signedPdf?.signedUrl ?? null
  }

  return Response.json({
    data: { ...data, signature_url: signatureUrl, guardian_signature_url: guardianSignatureUrl, pdf_url: pdfUrl }
  })
}

