import { enqueueJob } from '@/lib/queue'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

/**
 * POST /api/consent-forms/submissions/[id]/resend
 * Re-sends the signed PDF to the signer's email address.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  const ip = request.headers.get('x-forwarded-for') ?? auth.user.id
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })

  const { id } = await params
  const supabase = await createClient()
  const { data, error } = await supabase
    .from('consent_form_submissions')
    .select('id, signer_email, signer_name, pdf_path, pdf_generated_at, studio_id, soft_deleted_at')
    .eq('id', id)
    .eq('studio_id', auth.studioId)
    .single()

  if (error || !data) {
    return Response.json({ error: 'not_found' }, { status: 404 })
  }

  if (data.soft_deleted_at) {
    return Response.json({ error: 'submission_deleted' }, { status: 410 })
  }

  if (!data.signer_email) {
    return Response.json({ error: 'no_email_address' }, { status: 422 })
  }

  if (!data.pdf_path) {
    return Response.json({ error: 'pdf_not_ready' }, { status: 422 })
  }

  try {
    await enqueueJob('send-email', {
      to: data.signer_email,
      template: 'consent-pdf',
      data: { submissionId: id, signerName: data.signer_name, studioId: data.studio_id },
    })
  } catch (err) {
    logger.error({ err, id }, 'failed to enqueue consent PDF resend email')
    return Response.json({ error: 'queue_error' }, { status: 500 })
  }

  await logAuditAction(auth.user.id, 'consent_submission.pdf_resent', { type: 'consent_form_submission', id }, { signer_email: data.signer_email }, auth.studioId)
  return Response.json({ success: true })
}

