import { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

/**
 * GET /api/consent-forms/submissions/bulk-export
 * Streams a ZIP archive of PDFs for the requested submission IDs.
 * Query params: ids (comma-separated UUIDs)
 */
export async function GET(request: NextRequest) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  const ip = request.headers.get('x-forwarded-for') ?? auth.user.id
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const idsParam = searchParams.get('ids')
  if (!idsParam) return Response.json({ error: 'ids required' }, { status: 400 })

  const ids = idsParam.split(',').filter((id) => /^[0-9a-f-]{36}$/.test(id)).slice(0, 100)
  if (ids.length === 0) return Response.json({ error: 'no valid ids' }, { status: 400 })

  const supabase = await createClient()
  const { data: submissions, error } = await supabase
    .from('consent_form_submissions')
    .select('id, signer_name, signed_at, pdf_path')
    .in('id', ids)
    .eq('studio_id', auth.studioId)
    .is('soft_deleted_at', null)

  if (error) {
    logger.error({ err: error }, 'bulk export fetch failed')
    return Response.json({ error: 'database_error' }, { status: 500 })
  }

  const serviceRole = createServiceRoleClient()

  // Build ZIP using JSZip
  const JSZip = (await import('jszip')).default
  const zip = new JSZip()

  for (const sub of submissions ?? []) {
    if (!sub.pdf_path) continue

    const { data: fileData, error: dlError } = await serviceRole.storage
      .from('consent-forms')
      .download(sub.pdf_path)

    if (dlError || !fileData) {
      logger.warn({ submissionId: sub.id, path: sub.pdf_path }, 'bulk export: PDF download failed, skipping')
      continue
    }

    const buffer = Buffer.from(await fileData.arrayBuffer())
    const datePart = sub.signed_at ? new Date(sub.signed_at).toISOString().slice(0, 10) : 'unknown'
    const safeName = (sub.signer_name ?? 'unknown').replace(/[^a-zA-Z0-9_-]/g, '_')
    zip.file(`${datePart}_${safeName}_${sub.id.slice(0, 8)}.pdf`, buffer)
  }

  const zipBuffer = await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' })

  return new Response(zipBuffer, {
    status: 200,
    headers: {
      'Content-Type': 'application/zip',
      'Content-Disposition': `attachment; filename="consent-forms-${new Date().toISOString().slice(0, 10)}.zip"`,
      'Content-Length': String(zipBuffer.length),
    },
  })
}

