  const ip = request.headers.get('x-forwarded-for') ?? auth.user.id
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })

  const body = CreateRequestSchema.safeParse(await request.json().catch(() => null))
  if (!body.success) {
    return Response.json({ error: 'validation_error', details: body.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()
  const { data: rpcResult, error: rpcError } = await supabase.rpc('initiate_consent_request', {
    p_booking_id: body.data.booking_id,
    p_template_id: body.data.template_id,
    p_channel: body.data.channel,
  })

  if (rpcError) {
    logger.error({ err: rpcError }, 'initiate_consent_request failed')
    return Response.json({ error: 'database_error' }, { status: 500 })
  }

  const result = rpcResult as Record<string, unknown>

  // Enqueue email if channel includes email and we have a recipient
  if ((body.data.channel === 'email' || body.data.channel === 'both') && result['sent_to_email']) {
    try {
      const { enqueueJob } = await import('@/lib/queue')
      await enqueueJob('send-email', {
        to: result['sent_to_email'] as string,
        template: 'consent-request',
        data: {
          viewUrl: result['view_url'] as string,
          requestId: result['request_id'] as string,
          requestToken: result['request_token'] as string,
          studioId: auth.studioId,
        },
      })
    } catch (err) {
      logger.error({ err }, 'failed to enqueue consent request email — non-fatal')
    }
  }

  await logAuditAction(auth.user.id, 'consent_request.created', { type: 'consent_form_request', id: result['request_id'] as string }, { booking_id: body.data.booking_id, channel: body.data.channel, status: result['status'] }, auth.studioId)
  return Response.json({ data: rpcResult }, { status: 201 })
}

import { NextRequest } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

/**
 * GET /api/consent-requests/[id]
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  const { id } = await params
  const supabase = await createClient()
  const { data, error } = await supabase
    .from('consent_form_requests')
    .select('*')
    .eq('id', id)
    .eq('studio_id', auth.studioId)
    .single()

  if (error || !data) return Response.json({ error: 'not_found' }, { status: 404 })
  return Response.json({ data })
}

/**
 * DELETE /api/consent-requests/[id]
 * Cancels the request (owner/admin only).
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return Response.json({ error: 'forbidden' }, { status: 403 })
  }

  const ip = request.headers.get('x-forwarded-for') ?? auth.user.id
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })

  const { id } = await params
  const supabase = await createClient()

  const { data: existing, error: fetchError } = await supabase
    .from('consent_form_requests')
    .select('id, status')
    .eq('id', id)
    .eq('studio_id', auth.studioId)
    .single()

  if (fetchError || !existing) return Response.json({ error: 'not_found' }, { status: 404 })

  if (existing.status === 'signed') {
    return Response.json({ error: 'cannot_cancel_signed' }, { status: 422 })
  }

  const { error } = await supabase
    .from('consent_form_requests')
    .update({ status: 'cancelled' } as Record<string, unknown>)
    .eq('id', id)
    .eq('studio_id', auth.studioId)

  if (error) {
    logger.error({ err: error, id }, 'consent request cancel failed')
    return Response.json({ error: 'database_error' }, { status: 500 })
  }

  await logAuditAction(auth.user.id, 'consent_request.cancelled', { type: 'consent_form_request', id }, null, auth.studioId)
  return Response.json({ success: true })
}

import { NextRequest } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { enqueueJob } from '@/lib/queue'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

/**
 * POST /api/consent-requests/[id]/resend
 * Re-sends the consent signing link to the client.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const auth = await getAuthenticatedUser()
  if (!auth) return Response.json({ error: 'unauthorized' }, { status: 401 })

  const ip = request.headers.get('x-forwarded-for') ?? auth.user.id
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'rate_limit_exceeded' }, { status: 429 })

  const { id } = await params
  const supabase = await createClient()
  const { data: req, error } = await supabase
    .from('consent_form_requests')
    .select('*')
    .eq('id', id)
    .eq('studio_id', auth.studioId)
    .single()

  if (error || !req) return Response.json({ error: 'not_found' }, { status: 404 })

  if (req.status === 'signed') return Response.json({ error: 'already_signed' }, { status: 422 })
  if (req.status === 'cancelled') return Response.json({ error: 'request_cancelled' }, { status: 422 })

  const sentToEmail = (req as Record<string, unknown>)['sent_to_email'] as string | null
  if (!sentToEmail) return Response.json({ error: 'no_email_address' }, { status: 422 })

  const requestToken = (req as Record<string, unknown>)['request_token'] as string
  const viewUrl = `${process.env.NEXT_PUBLIC_APP_URL}/consent/${requestToken}`

  try {
    await enqueueJob('send-email', {
      to: sentToEmail,
      template: 'consent-request',
      data: { viewUrl, requestId: id, requestToken, studioId: auth.studioId },
    })
  } catch (err) {
    logger.error({ err, id }, 'failed to enqueue consent request resend')
    return Response.json({ error: 'queue_error' }, { status: 500 })
  }

  await logAuditAction(auth.user.id, 'consent_request.resent', { type: 'consent_form_request', id }, { sent_to_email: sentToEmail }, auth.studioId)
  return Response.json({ success: true })
}

