'use client'

import { useMemo } from 'react'
import { formatDistanceToNow, addYears, differenceInMonths } from 'date-fns'
import { cn } from '@/lib/utils'

interface RetentionCountdownProps {
  signedAt: string
  retentionYears: number
  className?: string
  /** When true, renders as a compact badge instead of full text */
  compact?: boolean
}

export function RetentionCountdown({ signedAt, retentionYears, className, compact = false }: RetentionCountdownProps) {
  const { label, colorClass } = useMemo(() => {
    const expiresAt = addYears(new Date(signedAt), retentionYears)
    const monthsLeft = differenceInMonths(expiresAt, new Date())

    const distance = formatDistanceToNow(expiresAt, { addSuffix: true })
    const label = `Auto-deletes ${distance}`

    const colorClass =
      monthsLeft < 6
        ? 'text-[var(--color-retention-crit)]'
        : monthsLeft < 24
          ? 'text-[var(--color-retention-warn)]'
          : 'text-[var(--color-retention-safe)]'

    return { label, colorClass }
  }, [signedAt, retentionYears])

  if (compact) {
    return (
      <span className={cn('text-xs font-medium', colorClass, className)}>
        {label}
      </span>
    )
  }

  return (
    <p className={cn('text-xs', colorClass, className)}>
      {label} (GDPR {retentionYears}-year retention)
    </p>
  )
}

'use client'

import { useRef, useCallback, useState, useEffect } from 'react'
import SignatureCanvas from 'react-signature-canvas'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'

interface SignaturePadProps {
  label?: string
  onDone: (png: string, svg: string) => void
  onClear?: () => void
  disabled?: boolean
  className?: string
}

/** Minimum number of points across all strokes to consider the signature valid */
const MIN_TOTAL_POINTS = 20
/** Minimum number of distinct strokes */
const MIN_STROKES = 3

/**
 * Converts the raw points from react-signature-canvas into an SVG path string.
 */
function pointsToSvgPath(data: Array<Array<{ x: number; y: number }>>): string {
  const paths: string[] = []
  for (const stroke of data) {
    if (stroke.length === 0) continue
    const [first, ...rest] = stroke
    const d = [`M ${first.x.toFixed(1)} ${first.y.toFixed(1)}`, ...rest.map((p) => `L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`)]
    paths.push(d.join(' '))
  }
  return paths.join(' ')
}

export function SignaturePad({ label, onDone, onClear, disabled = false, className }: SignaturePadProps) {
  const sigRef = useRef<SignatureCanvas>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const [hasValue, setHasValue] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [canvasWidth, setCanvasWidth] = useState(600)

  // Fit canvas to container width responsively
  useEffect(() => {
    if (!containerRef.current) return
    const observer = new ResizeObserver((entries) => {
      const entry = entries[0]
      if (entry) setCanvasWidth(Math.floor(entry.contentRect.width))
    })
    observer.observe(containerRef.current)
    return () => observer.disconnect()
  }, [])

  const handleStrokeEnd = useCallback(() => {
    if (!sigRef.current) return
    setHasValue(!sigRef.current.isEmpty())
    setError(null)
  }, [])

  const handleClear = useCallback(() => {
    sigRef.current?.clear()
    setHasValue(false)
    setError(null)
    onClear?.()
  }, [onClear])

  const handleDone = useCallback(() => {
    const pad = sigRef.current
    if (!pad) return

    if (pad.isEmpty()) {
      setError('Please provide your signature before continuing')
      return
    }

    // Count total points and strokes
    const data = (pad as unknown as { _data: Array<Array<{ x: number; y: number }>> })._data ?? []
    const totalPoints = data.reduce((sum, stroke) => sum + stroke.length, 0)

    if (totalPoints < MIN_TOTAL_POINTS || data.length < MIN_STROKES) {
      setError('Please draw a more complete signature (at least 3 strokes)')
      return
    }

    const png = pad.getTrimmedCanvas().toDataURL('image/png')
    const svgPathD = pointsToSvgPath(data)
    const canvas = pad.getTrimmedCanvas()
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${canvas.width}" height="${canvas.height}" viewBox="0 0 ${canvas.width} ${canvas.height}"><path d="${svgPathD}" stroke="white" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`

    setError(null)
    onDone(png, svg)
  }, [onDone])

  return (
    <div className={cn('flex flex-col gap-2', className)}>
      {label && (
        <p className="text-sm font-medium text-foreground">{label}</p>
      )}

      <div
        ref={containerRef}
        className={cn(
          'sig-pad-wrapper relative w-full overflow-hidden',
          hasValue && 'sig-has-value',
          disabled && 'opacity-50 pointer-events-none'
        )}
        style={{ touchAction: 'none' }}
        aria-label={label ?? 'Signature pad'}
      >
        <SignatureCanvas
          ref={sigRef}
          canvasProps={{
            width: canvasWidth,
            height: 180,
            className: 'w-full',
            style: { touchAction: 'none' },
          }}
          penColor="oklch(97% 0.01 264)"
          backgroundColor="transparent"
          onEnd={handleStrokeEnd}
        />

        {!hasValue && (
          <p className="pointer-events-none absolute inset-0 flex items-center justify-center text-sm text-muted-foreground select-none">
            Sign here
          </p>
        )}
      </div>

      {error && (
        <p className="text-xs text-destructive" role="alert">{error}</p>
      )}

      <div className="flex items-center gap-2">
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={handleClear}
          disabled={disabled || !hasValue}
        >
          Clear
        </Button>
        <Button
          type="button"
          size="sm"
          onClick={handleDone}
          disabled={disabled || !hasValue}
        >
          Done
        </Button>
      </div>
    </div>
  )
}

