import ReactMarkdown from 'react-markdown'
import rehypeSanitize, { defaultSchema } from 'rehype-sanitize'
import type { ConsentSection } from '@/types/consent'
import { cn } from '@/lib/utils'

/**
 * Restricted rehype-sanitize schema — allows only safe inline/block elements.
 * No scripts, no iframes, no event handlers.
 */
const SANITIZE_SCHEMA = {
  ...defaultSchema,
  tagNames: ['p', 'strong', 'em', 'ul', 'ol', 'li', 'a', 'br'],
  attributes: {
    ...defaultSchema.attributes,
    a: ['href'],
  },
}

interface SectionRendererProps {
  section: ConsentSection
  /** Preview mode — renders static placeholder for interactive sections */
  isPreview?: boolean
  className?: string
}

export function SectionRenderer({ section, isPreview = false, className }: SectionRendererProps) {
  return (
    <div className={cn('space-y-2', className)}>
      {renderSection(section, isPreview)}
    </div>
  )
}

function renderSection(section: ConsentSection, isPreview: boolean) {
  switch (section.kind) {
    case 'heading': {
      const Tag = section.level === 1 ? 'h1' : section.level === 2 ? 'h2' : 'h3'
      const sizeClass = section.level === 1 ? 'text-2xl' : section.level === 2 ? 'text-xl' : 'text-lg'
      return <Tag className={cn('font-semibold tracking-tight', sizeClass)}>{section.label}</Tag>
    }

    case 'paragraph':
      return (
        <div className="prose prose-invert prose-sm max-w-none text-sm text-muted-foreground leading-relaxed">
          <ReactMarkdown rehypePlugins={[[rehypeSanitize, SANITIZE_SCHEMA]]}>
            {section.body}
          </ReactMarkdown>
        </div>
      )

    case 'checkbox':
      return (
        <div className="space-y-2">
          {section.label && <p className="text-sm font-medium">{section.label}</p>}
          <div className="flex items-start gap-3">
            {isPreview ? (
              <div className="mt-0.5 h-4 w-4 shrink-0 rounded border border-border bg-muted" />
            ) : (
              <div className="mt-0.5 h-4 w-4 shrink-0 rounded border border-border bg-muted" />
            )}
            <div className="prose prose-invert prose-sm max-w-none text-sm text-muted-foreground">
              <ReactMarkdown rehypePlugins={[[rehypeSanitize, SANITIZE_SCHEMA]]}>
                {section.body}
