interface SectionEditorProps {
  section: ConsentSection
  onChange: (updated: ConsentSection) => void
  onRemove: () => void
  isActive: boolean
  onActivate: () => void
}

export function SectionEditor({ section, onChange, onRemove, isActive, onActivate }: SectionEditorProps) {
  const [isExpanded, setIsExpanded] = useState(isActive)

  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: section.id })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  }

  const update = useCallback(
    <K extends keyof ConsentSection>(key: K, value: ConsentSection[K]) => {
      onChange({ ...section, [key]: value } as ConsentSection)
    },
    [section, onChange]
  )

  const handleActivate = useCallback(() => {
    onActivate()
    setIsExpanded(true)
  }, [onActivate])

  return (
    <div
      ref={setNodeRef}
      style={style}
      data-dragging={isDragging ? 'true' : undefined}
      data-active={isActive ? 'true' : undefined}
      className={cn('builder-section group')}
      onClick={handleActivate}
    >
      {/* Header row */}
      <div className="flex items-center gap-2 p-3">
        <button
          type="button"
          {...attributes}
          {...listeners}
          className="cursor-grab text-muted-foreground hover:text-foreground focus-visible:outline-none"
          aria-label="Drag to reorder"
        >
          <GripVertical className="h-4 w-4" />
        </button>

        <div className="flex-1 min-w-0">
          <p className="truncate text-xs font-medium text-foreground">
            {section.label || `(${section.kind})`}
          </p>
          <p className="text-xs text-muted-foreground capitalize">{section.kind.replace(/_/g, ' ')}</p>
        </div>

        <div className="flex items-center gap-1 shrink-0">
          <button
            type="button"
            onClick={(e) => { e.stopPropagation(); setIsExpanded((v) => !v) }}
            className="rounded p-1 text-muted-foreground hover:text-foreground focus-visible:outline-none"
            aria-label={isExpanded ? 'Collapse section' : 'Expand section'}
          >
            {isExpanded ? <ChevronUp className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
          </button>
          <button
            type="button"
            onClick={(e) => { e.stopPropagation(); onRemove() }}
            className="rounded p-1 text-muted-foreground hover:text-destructive focus-visible:outline-none"
            aria-label="Remove section"
          >
            <Trash2 className="h-3.5 w-3.5" />
          </button>
        </div>
      </div>

      {/* Expanded editor */}
      {isExpanded && (
        <div className="border-t border-border p-3 space-y-3" onClick={(e) => e.stopPropagation()}>
          {/* Common: label */}
          {section.kind !== 'heading' && section.kind !== 'paragraph' && (
            <div className="space-y-1">
              <Label className="text-xs">Label</Label>
              <Input
                value={section.label}
                onChange={(e) => update('label', e.target.value)}
                placeholder="Section label shown to signer"
                className="h-8 text-xs"
              />
            </div>
          )}

          {/* Heading: label + level */}
          {section.kind === 'heading' && (
            <div className="space-y-1">
              <Label className="text-xs">Heading text</Label>
              <Input
                value={section.label}
                onChange={(e) => update('label', e.target.value)}
                className="h-8 text-xs"
              />
            </div>
          )}

          {/* Paragraph / checkbox / initials / ink_disclosure: body */}
          {(section.kind === 'paragraph' || section.kind === 'checkbox' || section.kind === 'initials' || section.kind === 'ink_disclosure') && (
            <div className="space-y-1">
              <Label className="text-xs">Body (Markdown)</Label>
              <Textarea
                value={section.kind === 'ink_disclosure' ? section.disclosure_text : (section as { body?: string }).body ?? ''}
                onChange={(e) => {
                  if (section.kind === 'ink_disclosure') {
                    update('disclosure_text' as keyof ConsentSection, e.target.value as ConsentSection[keyof ConsentSection])
                  } else {
                    update('body' as keyof ConsentSection, e.target.value as ConsentSection[keyof ConsentSection])
                  }
                }}
                rows={4}
                className="text-xs"
                placeholder="Supports **bold**, *italic*, [links](url)"
              />
            </div>
          )}

          {/* Text input: placeholder, min/max length */}
          {section.kind === 'text_input' && (
            <>
              <div className="space-y-1">
                <Label className="text-xs">Placeholder</Label>
                <Input
                  value={section.placeholder ?? ''}
                  onChange={(e) => update('placeholder' as keyof ConsentSection, e.target.value as ConsentSection[keyof ConsentSection])}
                  className="h-8 text-xs"
                />
              </div>
              <div className="grid grid-cols-2 gap-2">
                <div className="space-y-1">
                  <Label className="text-xs">Min length</Label>
                  <Input
                    type="number"
                    value={section.min_length ?? ''}
                    onChange={(e) => update('min_length' as keyof ConsentSection, (e.target.value ? parseInt(e.target.value, 10) : undefined) as ConsentSection[keyof ConsentSection])}
                    className="h-8 text-xs"
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-xs">Max length</Label>
                  <Input
                    type="number"
                    value={section.max_length ?? ''}
                    onChange={(e) => update('max_length' as keyof ConsentSection, (e.target.value ? parseInt(e.target.value, 10) : undefined) as ConsentSection[keyof ConsentSection])}
                    className="h-8 text-xs"
                  />
                </div>
              </div>
            </>
          )}

          {/* Date: min_age */}
          {section.kind === 'date' && (
            <div className="space-y-1">
              <Label className="text-xs">Minimum age (optional)</Label>
              <Input
                type="number"
                value={section.min_age ?? ''}
                onChange={(e) => update('min_age' as keyof ConsentSection, (e.target.value ? parseInt(e.target.value, 10) : undefined) as ConsentSection[keyof ConsentSection])}
                className="h-8 text-xs"
                placeholder="e.g. 18"
              />
            </div>
          )}

          {/* Dropdown: options */}
          {section.kind === 'dropdown' && (
            <div className="space-y-1">
              <Label className="text-xs">Options (one per line, format: value|label)</Label>
              <Textarea
                value={section.options.map((o) => `${o.value}|${o.label}`).join('\n')}
                onChange={(e) => {
                  const options = e.target.value
                    .split('\n')
                    .filter(Boolean)
                    .map((line) => {
                      const [value, ...rest] = line.split('|')
                      return { value: value.trim(), label: rest.join('|').trim() || value.trim() }
                    })
                  update('options' as keyof ConsentSection, options as ConsentSection[keyof ConsentSection])
                }}
                rows={4}
                className="text-xs font-mono"
                placeholder={`instagram|Instagram\nreferral|Friend or referral`}
              />
            </div>
          )}

          {/* Signature: signer type */}
          {section.kind === 'signature' && (
            <div className="space-y-1">
              <Label className="text-xs">Signer</Label>
              <select
                value={section.signer}
                onChange={(e) => update('signer' as keyof ConsentSection, e.target.value as ConsentSection[keyof ConsentSection])}
                className="h-8 w-full rounded-md border border-input bg-background px-2 text-xs"
              >
                <option value="client">Client</option>
                <option value="guardian">Guardian / parent</option>
              </select>
            </div>
          )}

          {/* Required toggle (not for heading/paragraph/reach_batch) */}
          {!['heading', 'paragraph', 'reach_batch_record'].includes(section.kind) && (
            <div className="flex items-center justify-between">
              <Label className="text-xs">Required</Label>
              <Switch
                checked={section.required}
                onCheckedChange={(checked) => update('required', checked)}
                aria-label="Required toggle"
              />
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragOverlay,
} from '@dnd-kit/core'
import type { DragEndEvent, DragStartEvent } from '@dnd-kit/core'
import {
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  arrayMove,
} from '@dnd-kit/sortable'
import { useState } from 'react'
import { SectionEditor } from './SectionEditor'
import type { ConsentSection } from '@/types/consent'
import { cn } from '@/lib/utils'

interface SectionListProps {
  sections: ConsentSection[]
  onChange: (sections: ConsentSection[]) => void
}

export function SectionList({ sections, onChange }: SectionListProps) {
  const [activeId, setActiveId] = useState<string | null>(null)
  const [expandedId, setExpandedId] = useState<string | null>(null)

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  const handleDragStart = (event: DragStartEvent) => {
    setActiveId(event.active.id as string)
  }

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event
    setActiveId(null)

    if (!over || active.id === over.id) return

    const oldIndex = sections.findIndex((s) => s.id === active.id)
    const newIndex = sections.findIndex((s) => s.id === over.id)
    if (oldIndex === -1 || newIndex === -1) return

    const reordered = arrayMove(sections, oldIndex, newIndex).map((s, i) => ({ ...s, order: i }))
    onChange(reordered)
  }

  const handleChange = (index: number, updated: ConsentSection) => {
    const next = [...sections]
    next[index] = updated
    onChange(next)
  }

  const handleRemove = (index: number) => {
    const next = sections.filter((_, i) => i !== index).map((s, i) => ({ ...s, order: i }))
    onChange(next)
    setExpandedId(null)
  }

  const activeSection = activeId ? sections.find((s) => s.id === activeId) : null

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
    >
      <SortableContext items={sections.map((s) => s.id)} strategy={verticalListSortingStrategy}>
        <div className={cn('space-y-2', sections.length === 0 && 'hidden')}>
          {sections.map((section, index) => (
            <SectionEditor
              key={section.id}
              section={section}
              onChange={(updated) => handleChange(index, updated)}
              onRemove={() => handleRemove(index)}
              isActive={expandedId === section.id}
              onActivate={() => setExpandedId(section.id)}
            />
          ))}
        </div>
      </SortableContext>

      <DragOverlay>
        {activeSection && (
          <div className="builder-section opacity-90 p-3">
            <p className="text-xs font-medium text-foreground">{activeSection.label || `(${activeSection.kind})`}</p>
          </div>
        )}
      </DragOverlay>
    </DndContext>
  )
}
